INSERT OR IGNORE INTO tbl_trilha(cod_idef_tril,nom_tril,des_tril,txt_cont_tril,num_ord_exib,qtd_xp_reco) VALUES ('TRILHA-01','A importância da independência e responsabilidade financeira na juventude','Introdução à autonomia, organização e responsabilidade financeira.','Ter independência financeira não significa apenas possuir dinheiro. Significa conseguir tomar decisões conscientes sobre como usar sua renda, organizar gastos e assumir responsabilidade pelas próprias escolhas. Um dos primeiros passos é conhecer quanto dinheiro entra e quanto sai. Acompanhar receitas e despesas ajuda a evitar gastos maiores do que a renda disponível. Também é importante diferenciar uma compra necessária de uma compra por impulso. Planejar não significa deixar de aproveitar o dinheiro, mas encontrar equilíbrio entre necessidades atuais, desejos e objetivos futuros.',1,150);
INSERT OR IGNORE INTO tbl_trilha(cod_idef_tril,nom_tril,des_tril,txt_cont_tril,num_ord_exib,qtd_xp_reco) VALUES ('TRILHA-02','Como fazer o primeiro orçamento pessoal e organizar a mesada ou salário','Orçamento pessoal, receitas, despesas e organização mensal.',NULL,2,150);
INSERT OR IGNORE INTO tbl_trilha(cod_idef_tril,nom_tril,des_tril,txt_cont_tril,num_ord_exib,qtd_xp_reco) VALUES ('TRILHA-03','Distinção clara entre necessidades, desejos e consumo consciente','Como diferenciar prioridades de desejos e consumir com consciência.',NULL,3,150);
INSERT OR IGNORE INTO tbl_trilha(cod_idef_tril,nom_tril,des_tril,txt_cont_tril,num_ord_exib,qtd_xp_reco) VALUES ('TRILHA-04','Como evitar armadilhas comuns: cartão de crédito, compras por impulso e parcelamentos','Riscos do crédito, parcelamentos e decisões impulsivas.',NULL,4,150);
INSERT OR IGNORE INTO tbl_trilha(cod_idef_tril,nom_tril,des_tril,txt_cont_tril,num_ord_exib,qtd_xp_reco) VALUES ('TRILHA-05','Estratégias práticas para renegociar dívidas e sair do vermelho','Organização de dívidas e estratégias de renegociação.',NULL,5,150);
INSERT OR IGNORE INTO tbl_trilha(cod_idef_tril,nom_tril,des_tril,txt_cont_tril,num_ord_exib,qtd_xp_reco) VALUES ('TRILHA-06','Como montar a primeira reserva de emergência','Planejamento e construção de uma reserva financeira.',NULL,6,150);
INSERT OR IGNORE INTO tbl_trilha(cod_idef_tril,nom_tril,des_tril,txt_cont_tril,num_ord_exib,qtd_xp_reco) VALUES ('TRILHA-07','Entendendo o poder dos juros compostos a seu favor ao começar cedo','Conceitos de juros compostos aplicados ao longo do tempo.',NULL,7,150);
INSERT OR IGNORE INTO tbl_trilha(cod_idef_tril,nom_tril,des_tril,txt_cont_tril,num_ord_exib,qtd_xp_reco) VALUES ('TRILHA-08','Introdução simples aos investimentos básicos (Tesouro Direto, CDBs e Caixinhas)','Primeiros conceitos sobre investimentos de baixo nível de complexidade.',NULL,8,150);
INSERT OR IGNORE INTO tbl_trilha(cod_idef_tril,nom_tril,des_tril,txt_cont_tril,num_ord_exib,qtd_xp_reco) VALUES ('TRILHA-09','Definição e planejamento de metas financeiras (viagens, estudos, primeiro carro)','Criação e acompanhamento de objetivos financeiros.',NULL,9,150);
INSERT OR IGNORE INTO tbl_trilha(cod_idef_tril,nom_tril,des_tril,txt_cont_tril,num_ord_exib,qtd_xp_reco) VALUES ('TRILHA-10','Cuidados com golpes na internet, apostas/bets e promessas de dinheiro fácil','Prevenção contra golpes, apostas e promessas financeiras enganosas.',NULL,10,150);
INSERT OR IGNORE INTO tbl_trilha(cod_idef_tril,nom_tril,des_tril,txt_cont_tril,num_ord_exib,qtd_xp_reco) VALUES ('TRILHA-11','Noções essenciais sobre trabalho, fontes de renda extra e empreendedorismo jovem','Renda, trabalho e possibilidades de geração de renda extra.',NULL,11,150);
INSERT OR IGNORE INTO tbl_trilha(cod_idef_tril,nom_tril,des_tril,txt_cont_tril,num_ord_exib,qtd_xp_reco) VALUES ('TRILHA-12','Transição para a vida adulta: custos de morar sozinho e planejamento de longo prazo','Custos da vida adulta e organização financeira de longo prazo.',NULL,12,150);
