INSERT OR IGNORE INTO tbl_missao(cod_idef_miss,nom_miss,des_miss,nom_tipo_miss,qtd_meta_miss,qtd_xp_reco) VALUES ('MISSAO-02','Desafio 50/30/20','Dividir sua renda ou mesada entre necessidades, desejos e planejamento financeiro.','PLANEJAMENTO',1,100);
INSERT OR IGNORE INTO tbl_missao(cod_idef_miss,nom_miss,des_miss,nom_tipo_miss,qtd_meta_miss,qtd_xp_reco) VALUES ('MISSAO-03','Permanência — Assista 10 Aulas','Complete 10 conteúdos ou aulas das trilhas de aprendizagem.','CONTEUDOS',10,100);
