INSERT OR IGNORE INTO tbl_cenario_financeiro(cod_idef_cena,nom_cena,des_cena,ind_cena_publ) VALUES ('CENARIO-01','Comprar um notebook','Você possui R$ 3.000 disponíveis e precisa comprar um notebook que custa R$ 2.500. Qual decisão você tomaria?',1);
INSERT OR IGNORE INTO tbl_cenario_financeiro(cod_idef_cena,nom_cena,des_cena,ind_cena_publ) VALUES ('CENARIO-02','Recebeu o primeiro salário','Você recebeu seu primeiro salário de R$ 2.000. Depois de pagar suas despesas essenciais, restaram R$ 800. O que você faria com esse dinheiro?',1);
INSERT OR IGNORE INTO tbl_opcao_cenario(cod_idef_opca,cod_idef_cena,nom_opca,des_cons,num_ord_opca) VALUES ('OPCAO-01-01','CENARIO-01','Comprar à vista','Decisão: Comprar à vista. Saldo inicial: R$ 3.000,00. Valor do notebook: R$ 2.500,00. Saldo restante: R$ 500,00. Dívida: R$ 0,00. Consequência: você evita juros e não cria uma dívida, mas utiliza grande parte do dinheiro disponível e fica com uma reserva menor para emergências.',1);
INSERT OR IGNORE INTO tbl_opcao_cenario(cod_idef_opca,cod_idef_cena,nom_opca,des_cons,num_ord_opca) VALUES ('OPCAO-01-02','CENARIO-01','Parcelar','Decisão: Parcelar o notebook. Parcelamento: 10 parcelas de R$ 290,00. Valor total pago: R$ 2.900,00. Custo adicional: R$ 400,00. Consequência: você preserva parte do dinheiro no curto prazo, mas assume uma dívida mensal e paga R$ 400,00 a mais.',2);
INSERT OR IGNORE INTO tbl_opcao_cenario(cod_idef_opca,cod_idef_cena,nom_opca,des_cons,num_ord_opca) VALUES ('OPCAO-01-03','CENARIO-01','Comprar depois','Decisão: Esperar para comprar. Você mantém sua reserva financeira e não assume uma dívida. Em contrapartida, precisará esperar mais tempo para adquirir o notebook.',3);
INSERT OR IGNORE INTO tbl_opcao_cenario(cod_idef_opca,cod_idef_cena,nom_opca,des_cons,num_ord_opca) VALUES ('OPCAO-02-01','CENARIO-02','Gastar tudo','Decisão: gastar todo o dinheiro restante. Você aproveita o dinheiro imediatamente, mas termina o mês sem nenhuma reserva para emergências ou objetivos futuros.',1);
INSERT OR IGNORE INTO tbl_opcao_cenario(cod_idef_opca,cod_idef_cena,nom_opca,des_cons,num_ord_opca) VALUES ('OPCAO-02-02','CENARIO-02','Dividir o dinheiro','Decisão: dividir os R$ 800,00 entre lazer e reserva. Você consegue aproveitar parte do salário e ao mesmo tempo começa a construir uma reserva.',2);
INSERT OR IGNORE INTO tbl_opcao_cenario(cod_idef_opca,cod_idef_cena,nom_opca,des_cons,num_ord_opca) VALUES ('OPCAO-02-03','CENARIO-02','Guardar tudo','Decisão: guardar todo o dinheiro restante. Sua reserva cresce mais rapidamente, mas você abre mão de utilizar parte do salário para lazer ou consumo pessoal.',3);
